'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "toDate(datum[''Début''])",
      "as": "deb"
    },
    {
      "calculate": "toDate(datum[''Fin''])",
      "as": "fin"
    },
    {
      "calculate": "toDate(datum[''Date de référence''])",
      "as": "today"
    },
    {
      "calculate": "isValid(datum[''Avancement projet'']) ? max(0, min(1, datum[''Avancement projet''])) : 0",
      "as": "pct"
    },
    {
      "calculate": "datum[''Statut''] == ''En retard'' && +datum.today > +datum.fin",
      "as": "late"
    },
    {
      "calculate": "+datum.fin > +datum.deb ? datum.fin : toDate(+datum.deb + 86400000)",
      "as": "finVis"
    },
    {
      "calculate": "toDate(+datum.deb + datum.pct * (+datum.finVis - +datum.deb))",
      "as": "achEnd"
    },
    {
      "calculate": "datum.late ? datum.today : datum.finVis",
      "as": "barEnd"
    },
    {
      "calculate": "format(datum.pct * 100, ''.0f'') + '' %''",
      "as": "pctTxt"
    },
    {
      "calculate": "datum[''Jours de retard''] > 0 ? ''+'' + datum[''Jours de retard''] + '' j'' : ''—''",
      "as": "retardTxt"
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "deb",
          "as": "chefStart"
        },
        {
          "op": "max",
          "field": "barEnd",
          "as": "chefEnd"
        },
        {
          "op": "count",
          "as": "nChef"
        }
      ],
      "groupby": [
        "Chef de projet"
      ]
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rn"
        }
      ],
      "sort": [
        {
          "field": "chefStart"
        },
        {
          "field": "Chef de projet"
        },
        {
          "field": "deb"
        },
        {
          "field": "Projet"
        }
      ]
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "c"
        }
      ],
      "sort": [
        {
          "field": "chefStart"
        },
        {
          "field": "Chef de projet"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "rn",
          "as": "firstRn"
        }
      ],
      "groupby": [
        "Chef de projet"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "count",
          "as": "nProj"
        },
        {
          "op": "max",
          "field": "c",
          "as": "nChefs"
        },
        {
          "op": "min",
          "field": "deb",
          "as": "minDeb"
        },
        {
          "op": "max",
          "field": "barEnd",
          "as": "maxEnd"
        }
      ]
    },
    {
      "calculate": "min(1, 690 / (40 * datum.nChefs + 45 * datum.nProj))",
      "as": "k"
    },
    {
      "calculate": "101 + datum.k * (40 * datum.c + 45 * (datum.rn - 1))",
      "as": "yP"
    },
    {
      "calculate": "101 + datum.k * (40 * (datum.c - 1) + 45 * (datum.firstRn - 1))",
      "as": "yC"
    },
    {
      "calculate": "min(11, 11 * datum.k)",
      "as": "hb"
    },
    {
      "calculate": "datum.yP - datum.hb",
      "as": "yP1"
    },
    {
      "calculate": "datum.yP + datum.hb",
      "as": "yP2"
    },
    {
      "calculate": "datum.yP - 7 * datum.k",
      "as": "yNom"
    },
    {
      "calculate": "datum.yP + 9 * datum.k",
      "as": "yDates"
    },
    {
      "calculate": "datum.yC - 9",
      "as": "yC1"
    },
    {
      "calculate": "datum.yC + 9",
      "as": "yC2"
    },
    {
      "calculate": "datum.yP - 9",
      "as": "yL1"
    },
    {
      "calculate": "datum.yP + 9",
      "as": "yL2"
    },
    {
      "calculate": "{''En retard'': ''#EF5B3A'', ''En cours'': ''#3F86C8'', ''Pas commencé'': ''#B4BFB9'', ''Terminé'': ''#00734E''}[datum[''Statut'']] || ''#B4BFB9''",
      "as": "cFonce"
    },
    {
      "calculate": "{''En retard'': ''#FBDCD3'', ''En cours'': ''#DCE9F6'', ''Pas commencé'': ''#EEF1EF'', ''Terminé'': ''#E1F2E8''}[datum[''Statut'']] || ''#EEF1EF''",
      "as": "cClair"
    }
  ],
  "layer": [
