        },
        {
          "calculate": "(year(datum.domEnd) - year(datum.minDeb)) * 12 + month(datum.domEnd) - month(datum.minDeb)",
          "as": "nM"
        },
        {
          "calculate": "sequence(0, datum.nM + 1)",
          "as": "seq"
        },
        {
          "flatten": [
            "seq"
          ],
          "as": [
            "i"
          ]
        },
        {
          "calculate": "datetime(year(datum.minDeb), month(datum.minDeb) + datum.i, 1)",
