        },
        {
          "calculate": "''T'' + (floor(month(datum.mStart) / 3) + 1) + '' '' + year(datum.mStart)",
          "as": "qLabel"
        },
        {
          "calculate": "[''janv.'',''févr.'',''mars'',''avr.'',''mai'',''juin'',''juil.'',''août'',''sept.'',''oct.'',''nov.'',''déc.''][month(datum.mStart)]",
